"""The week of 7 Dec 2026's hero options (Mon, Wed, Fri), as data. Run by work/assemble.py. Every fact here is quoted
or summarised from the research files in ../research/ (each candidate's primary and second source, opened by the
research readers on 26 and 27 Nov 2026)."""

RP = ("Act as a research analyst for a publication read by people who make the calls or make the work in music, film, "
      "games, publishing, art, media and sport. Plain question: {q} Find, from primary sources first (the organisation's "
      "own pages, filings, official announcements, the outlet that first reported it), the newest dated facts from "
      "{frm} to 7 December 2026 on: {find}. Work through the 5 Whys, starting from the plain question: Why 1 asks {why1}. "
      "For each Why give one answer backed by two primary sources on different domains, each with its URL, its "
      "publication date and a short verbatim quote. Give the strongest counter-evidence for each Why, or say \"none "
      "found\" and the scope you searched. Stop where the evidence runs out and say why; never pad to five. End on what "
      "the evidence shows and one open question for the reader. No forecasts, odds, scores or dated calls. Every claim "
      "comes with its source and its date.")
WHY1 = {'mon': 'who pays, and why the price moved', 'wed': 'how it is built, and what broke',
        'fri': 'where the claim and the reality part'}


def rp(day, q, frm, find):
    return RP.format(q=q, frm=frm, find=find, why1=WHY1[day])


